const EMPTY_DAY = FIELDS.reduce((acc, f) => ({ ...acc, [f.key]: "" }), { nota: 0 });

function shiftDays(obj, offset) {
  const out = {};
  Object.keys(obj).forEach((k) => {
    out[Number(k) + offset] = obj[k];
  });
  return out;
}

